  const tutorialLink=id=>movementTutorials[id]?`<a class="outline-button" href="${movementTutorials[id][1]}" target="_blank" rel="noopener noreferrer">查看${movementTutorials[id][0]} ↗</a>`:'';
  function demoControls(id){const info=athleteMotionInfo(id);if(info.static)return `<p class="static-pose-caption">${escape(info.caption||info.gaze)}</p>`;if(!info.available)return '<p class="animation-status-note">此动作的 A 方案演示尚未完成。请先阅读下方要点。</p>';return `<div class="demo-controls"><span>${escape(info.view)}视角 · 四个关键姿势慢放</span><button class="outline-button" data-action="pause-demo">暂停演示</button></div><div class="pose-steps" aria-label="逐步查看姿势">${info.phases.map((label,i)=>`<button data-action="pose-frame" data-pose-frame="${i}" aria-pressed="false">${i+1} · ${escape(label)}</button>`).join('')}</div><p class="gaze-note">${escape(info.gaze)}</p>`;}
  function openMovement(id){const m=move(id);if(!m)return;const info=athleteMotionInfo(id);openModal(m.name,`${mascotName()} · A 方案运动员 · ${m.focus}`,`<div class="demo-large" id="demoStage">${demo(id)}</div><div class="demo-buddy-bar">${buddyToggle(id)}</div>${demoControls(id)}<div class="movement-metrics"><span><b>${m.sets}</b>建议组数</span><span><b style="font-size:16px">${escape(m.reps)}</b>每组参考</span><span><b style="font-size:16px">${escape(m.rest)}</b>组间休息</span></div><ol class="cue-list">${m.cues.map(c=>`<li>${c}</li>`).join('')}</ol><p class="info-note">动作幅度与次数按能力调整，疼痛时停止。图示辅助理解动作路径，可配合合格教练检查实际姿势。</p><div class="tutorial-links">${tutorialLink(id)}<a class="outline-button" href="https://www.xiaohongshu.com/search_result?keyword=${encodeURIComponent(m.name+' 新手 动作教学')}" target="_blank" rel="noopener noreferrer">在小红书搜索这个动作 ↗</a></div>`);}

  function openMeal(id){const m=mealData.find(x=>x.id===id);if(!m)return;const items=mealPortion(m);openModal(m.title,'按食材重量计算，包含用油与酱料。',`<div class="food-visual" style="height:175px">${plate(m.kind)}</div><form id="mealForm" data-meal-id="${m.id}"><table class="meal-table"><thead><tr><th>食材 / 称量口径</th><th>重量 g</th><th>kcal/100g</th></tr></thead><tbody>${items.map((i,n)=>`<tr><td>${i[0]}</td><td><input type="number" name="g${n}" min="0" max="2000" step="1" value="${i[1]}" data-density="${i[2]}" required aria-label="${i[0]}克重"></td><td>${i[2]}</td></tr>`).join('')}</tbody></table><div class="meal-sum"><span>本餐参考合计</span><div><b id="mealTotal">${mealKcal(items)}</b> <span>kcal</span></div></div><p class="info-note">计算：克重 × 每 100g 热量 ÷ 100，再求和。数值为常见食材示例，实际请以包装营养标示或可靠食物成分表为准。餐盘插画不代表真实份量。</p><div class="form-footer"><small>${fmt(selectedDate)} · 记录实际吃下的份量</small><button type="submit" class="primary-button">记录这顿饭 ✓</button></div></form>`);}
  function customMeal(){if(!requireProfile())return;openModal('记录其他饮食','可以参考食品包装或你使用的食物成分数据库。',`<form id="customMealForm"><div class="form-grid"><label class="field span-2">食物名称<input name="name" maxlength="40" placeholder="例如：午餐便当" required></label><label class="field span-2">实际摄入热量 / kcal<input type="number" name="calories" min="1" max="6000" step="1" required placeholder="输入本次饮食的总热量"></label></div><p class="info-note">不确定时可以填写近似值。记录是帮助观察习惯，不需要追求完美。</p><div class="form-footer"><small>${fmt(selectedDate)}</small><button class="primary-button">保存这次记录</button></div></form>`);}
  function openAdjust(){if(!requireProfile())return;openModal('调整计划','选择如何调整后续安排，休息日依旧保留。',`<form id="adjustForm"><label class="field" style="margin-bottom:15px">哪一天的训练未完成？<input name="missedDate" type="date" min="${profile().startDate}" max="${today}" value="${selectedDate>today?today:selectedDate<profile().startDate?today:selectedDate}" required></label><div class="adjust-options"><label class="adjust-option"><input name="mode" value="extend" type="radio" checked><span><b>给自己多一点时间</b><small>顺延阶段复盘日，继续下一次原定训练。</small></span></label><label class="adjust-option"><input name="mode" value="current" type="radio"><span><b>分到本训练周期</b><small>只增加少量轻活动，每天最多增加 5 分钟。</small></span></label><label class="adjust-option"><input name="mode" value="next" type="radio"><span><b>分到下一训练周期</b><small>分配到下一周期运动日，保留休息日。</small></span></label></div><div id="adjustPreview" class="result-panel"></div><div class="form-error" id="adjustError" role="alert"></div><div class="form-footer"><small>余量不强行补齐，转为顺延复盘。<br>饮食偏离不会折算成补练。</small><button class="primary-button" id="applyAdjust">确认调整</button></div></form>`);updateAdjustmentPreview();}
  let pendingAdjustment=null;
  function updateAdjustmentPreview(){const f=$('#adjustForm');if(!f)return;const values=new FormData(f),date=values.get('missedDate'),mode=values.get('mode');pendingAdjustment=null;$('#adjustError').textContent='';if(!date||date>today||date<profile().startDate){$('#adjustPreview').textContent='请选择计划开始后、今天及以前的日期。';$('#applyAdjust').disabled=true;return;}if(FitEngine.schedule(profile(),date).type==='rest'||entry(date).workout||state.changes.some(c=>c.missedDate===date)){$('#adjustPreview').textContent='该日为休息日、已完成，或已经调整过。请选择尚未完成的运动日。';$('#applyAdjust').disabled=true;return;}const result=FitEngine.redistribute(profile(),date,mode,state.adjustments,today);const future=result.additions;pendingAdjustment={...result,missedDate:date,mode};$('#applyAdjust').disabled=false;$('#adjustPreview').innerHTML=`${future.length?future.map(a=>`${fmt(a.date)}：增加 ${a.minutes} 分钟轻松步行`).join('<br>'):'本次不额外增加训练量。'}<br>阶段复盘日${pendingAdjustment.extensionDays?`顺延 ${pendingAdjustment.extensionDays} 天，至 ${fmt(addDays(profile().targetDate,pendingAdjustment.extensionDays))}`:'保持不变'}。<br><small>分摊是少量额外活动的安排，不代表补回等量训练效果。</small>`;}
  function begin(){if(!requireProfile())return;if(selectedDate!==today){toast('训练打卡仅开放今天。可以查看其他日期的安排。');return;}const d=plan();if(d.type==='strength'?d.moves.length>0&&d.moves.every(m=>moveDone(m.id)):entry().workout){openModal('今天的训练部分已记录。','有氧活动可以继续单独记录，不必重复力量训练。',`<div class="success-mascot">${mascotArt(mascot(),'cheer')}</div><p class="success-text">${escape(d.title)} 已留下记录。按计划恢复，感受身体的变化。</p><button class="primary-button" data-action="close" style="width:100%">好，继续按自己的节奏</button>`);return;}if(d.type!=='strength'){openModal(d.type==='rest'?'记录今天的恢复':'记录今天的轻活动','确认实际完成后再打卡。',`<div class="rest-art">${d.type==='rest'?'☁':'↝'}</div><p class="success-text">${d.type==='rest'?'正常饮食、规律睡眠，给恢复留出空间。':`今天建议轻松活动约 ${d.cardio?.targetMinutes||20} 分钟。可以使用应用计时，也可以记录已经完成的活动。`}</p><button class="primary-button" style="width:100%" data-action="finish">${d.type==='rest'?'记录恢复日':'我已完成轻活动'} ✓</button>`);return;}session={date:selectedDate,index:0,completed:Object.fromEntries(d.moves.map((m,i)=>[i,moveDone(m.id)?m.sets:Math.min(m.sets,Number(entry().setsCompleted?.[m.id])||0)])),moves:d.moves};showSession();}
  function showSession(){const s=session,m=s.moves[s.index],lib=move(m.id),count=s.completed[s.index]||0;openModal(lib.name,'热身 5 分钟后开始。每组保留约 2–3 次余力，按自己的节奏练习。',`<div class="demo-buddy-bar">${buddyToggle()}</div><div class="session-step">${mascotName()}陪练 · 动作 ${s.index+1} / ${s.moves.length} · ${escape(plan(s.date).title)}</div><div class="demo-large" id="demoStage">${demo(m.id)}</div><p class="session-dose">${escape(m.reps)} / 组 · 组间休息 ${m.rest} 秒</p>${demoControls(m.id)}<ol class="cue-list">${lib.cues.map(c=>`<li>${c}</li>`).join('')}</ol>${m.note?`<p class="info-note">${escape(m.note)}</p>`:''}${m.seconds?`<div class="work-timer"><span id="workTimer">本组 ${m.seconds} 秒${m.reps.includes('侧')?' / 每侧':''}</span><button class="outline-button" data-action="work-timer">开始本组计时 ◷</button><small>计时结束后自行确认完成；双侧动作换边后再计时一次。</small></div>`:''}<div class="set-row">${Array.from({length:m.sets},(_,i)=>`<button class="set-button ${i<count?'done':''}" data-set="${i}" ${i!==count?'disabled':''}>${i<count?'✓ 已完成':'完成第 '+(i+1)+' 组'}</button>`).join('')}</div><div class="demo-controls"><span id="restTimer">完成后确认组数</span><button class="small-link" data-action="rest">休息 ${m.rest} 秒 ◷</button></div><div class="form-footer"><button class="outline-button" data-action="previous" ${s.index===0?'disabled':''}>上一个动作</button><button class="primary-button" data-action="next" ${count<m.sets?'disabled':''}>${s.index===s.moves.length-1?'完成力量部分 ✓':'下一个动作 →'}</button></div>`);}
  function startSetTimer(){if(!session)return;const m=session.moves[session.index];if(!m.seconds)return;clearInterval(timer);const end=Date.now()+m.seconds*1000;const tick=()=>{const label=$('#workTimer');if(!label){clearInterval(timer);return;}const left=Math.max(0,Math.ceil((end-Date.now())/1000));label.textContent=left?`本组剩余 ${left} 秒 · 正常呼吸`:'本组计时结束';if(!left)clearInterval(timer);};tick();timer=setInterval(tick,250);}

  function finish(){const date=session?.date||selectedDate;if(date!==today)return;const d=plan(date);const log=editEntry(date);log.workout=true;log.title=d.type==='rest'?'恢复日':d.title;if(d.type==='strength'){log.exerciseCompletions=Object.fromEntries(d.moves.map(m=>[m.id,true]));log.setsCompleted=Object.fromEntries(d.moves.map(m=>[m.id,m.sets]));}save();clearInterval(timer);session=null;render();openModal('训练已完成','记住这份认真，也给身体留出恢复的时间。',`<div class="success-mascot">${mascotArt(mascot(),'cheer')}</div><p class="success-text">${d.extraMinutes?`还有 ${d.extraMinutes} 分钟轻松步行，按状态选择。<br>`:''}${d.type==='strength'?'力量部分已记录。有氧可在今日计划中另行计时，最后轻松放松 5 分钟。':'今天的安排已记录，继续好好吃饭和休息。'}</p><button class="primary-button" style="width:100%" data-action="close">完成 ✓</button>`);}
  function method(){openModal('有依据，也有边界。','这是一般健康成人的习惯管理原型，不提供诊断或疗效承诺。',`<div class="method-copy"><h3>体脂：公式粗估，个人误差可能更大</h3><p>未填体脂时：体脂% = 1.20 × BMI + 0.23 × 年龄 − 10.8 × 性别系数 − 5.4；男为1，女为0。BMI = kg ÷ m²。原研究标准估计误差约 4.1 个百分点，这不是个人误差保证范围。高肌肉量或特殊体型可能偏差较大。</p><a href="https://pubmed.ncbi.nlm.nih.gov/2043597/" target="_blank" rel="noopener">Deurenberg 等，1991 · 原始研究 ↗</a><h3>热量：先维持，减脂也温和</h3><p>Mifflin 静息能量估算：10×kg + 6.25×cm − 5×年龄，男性再加5，女性减161。乘以你选择的活动系数 1.2 / 1.35 / 1.5 得到粗略全天消耗。活动系数是模型假设。默认维持能量；选择减脂时采用不超过约10%、最多250 kcal的小缺口。若结果低于女性1500或男性1800 kcal，首版停止自动推荐并建议专业评估；这是产品保守门槛，不是通用安全线。数值取整仅便于使用，不代表精确。</p><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">Mifflin 等，1990 · 原始研究 ↗</a><p>蛋白质按约 1.6g/kg 分配、脂肪约占30%能量，其余为碳水；这是首版的通用配餐规则，非个人营养处方。特殊饮食需求请咨询营养专业人士。</p><h3>训练：从少量开始，逐渐积累</h3><p>全身、下肢与核心主题轮换，力量日之间穿插轻有氧，保留恢复日。新手从少量组数开始，动作质量稳定后再进阶；跳跃不是必选动作。每组次数与组间休息是通用起点，可延长休息或减少次数。长期可逐步接近成人每周150分钟中等强度活动及至少两天力量活动的公共健康建议；首周不强求达标。男女共用基础动作，性别不决定训练能力。</p><p><a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener">CDC 成人活动指南 ↗</a> · <a href="https://www.nhs.uk/live-well/exercise/strength-exercises/" target="_blank" rel="noopener">NHS 基础力量动作 ↗</a></p><p>“全身燃脂”“下肢塑型”是训练侧重点名称，不代表局部减脂或确定消耗。有氧计时使用设备时间累计，里程手动输入，不提供 GPS 路线与运动热量推算。游泳建议上岸后补记。</p>${(FitEngine.trainingSources||[]).filter(x=>!x.url.includes('cdc.gov')&&!x.url.includes('nhs.uk')).map(x=>`<p><a href="${escape(x.url)}" target="_blank" rel="noopener">${escape(x.title)} ↗</a></p>`).join('')}<h3>漏练调整：只调整安排，不惩罚身体</h3><p>可顺延复盘，或把少量轻活动分到本/下周期的未来运动日，每日最多加5分钟，休息日不加量；不足的安排空间转为顺延。食物不会折算成惩罚运动，不扣减次日饮食。</p><h3>适用范围与数据</h3><p>首版自动计划限18–64岁、BMI 18.5–34.9的一般健康成人；这是产品保守适用范围，不是诊断分界。孕期、哺乳期、有伤痛或疾病、进食障碍等情况请先寻求专业指导。体态关注只用于一般提示，不能诊断或矫正。阶段复盘日期不等于“薄肌达成日”。</p><a href="https://www.niddk.nih.gov/health-information/weight-management/body-weight-planner" target="_blank" rel="noopener">NIDDK 体重计划器适用边界 ↗</a><p>当前原型无账号、云同步或教练审核，数据保存在本浏览器本地存储。照片在当前浏览器内识别，不发送到识别服务器；首次使用需从外部服务下载识别组件与模型。只保留随饮食记录保存的小缩略图，不保存原图。清理浏览器或更换设备不会保留记录；可在身体档案中删除全部数据。</p></div>`);}
  document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b)return;if(b.dataset.nutritionTab){nutritionTab=b.dataset.nutritionTab;view='nutrition';render();return;}if(b.dataset.foodId){openSingleFood(b.dataset.foodId);return;}if(b.dataset.foodFilter){foodFilter=b.dataset.foodFilter;render();return;}if(b.dataset.view){view=b.dataset.view;render();window.scrollTo({top:0});return;}if(b.dataset.move){openMovement(b.dataset.move);return;}if(b.dataset.meal){openMeal(b.dataset.meal);return;}if(b.dataset.date){selectedDate=b.dataset.date;render();return;}if(b.dataset.week){selectedDate=addDays(selectedDate,+b.dataset.week);render();return;}if(b.dataset.deleteMeal!==undefined){editEntry().meals.splice(+b.dataset.deleteMeal,1);save();render();return;}if(b.dataset.set!==undefined&&session){const next=+b.dataset.set,count=session.completed[session.index]||0;if(next===count){const m=session.moves[session.index];session.completed[session.index]=count+1;const log=editEntry(session.date);initializeExerciseLog(log,plan(session.date));log.setsCompleted=log.setsCompleted||{};log.setsCompleted[m.id]=count+1;const newlyDone=count+1===m.sets&&!log.exerciseCompletions[m.id];log.exerciseCompletions[m.id]=count+1>=m.sets;const d=plan(session.date);log.workout=d.moves.length>0&&d.moves.every(x=>log.exerciseCompletions[x.id]===true);if(log.workout)log.title=d.title;save();clearInterval(timer);render();showSession();if(newlyDone)celebrateMove(m.id);}return;}const a=b.dataset.action;if(!a)return;event.preventDefault();if(a==='toggle-character'){state.character=mascot()==='spongebob'?'patrick':'spongebob';save();render();if(session){clearInterval(timer);showSession();}else if(b.dataset.demoId){openMovement(b.dataset.demoId);}else render();toast(`已切换为${mascotName()}`);}else if(a==='model-views'){if(typeof renderAthleteModelViews==='function')openModal('角色多视角','',`<div class="model-views-stage">${renderAthleteModelViews(mascot())}</div>`);}else if(a==='close')closeModal();else if(a==='profile')openProfile();else if(a==='today'){selectedDate=today;render();}else if(a==='complete-move')toggleMoveCompletion(b.dataset.completeMove);else if(a==='cardio')openCardio(b.dataset.cardioType);else if(a==='work-timer')startSetTimer();else if(a==='start')begin();else if(a==='finish')finish();else if(a==='pose-frame'){const stage=$('#demoStage');let svg=$('svg.move-demo',stage);if(!svg)return;const frame=Number(b.dataset.poseFrame),duration=Number(svg.dataset.duration),width=Number(svg.dataset.cellWidth);stage.classList.remove('is-paused');if(svg.dataset.vector){const id=svg.dataset.move,c=svg.dataset.character;stage.innerHTML=renderAthleteVector(id,c,frame);svg=$('svg.move-demo',stage);svg.dataset.manualPhase=String(frame);}svg.pauseAnimations();svg.setCurrentTime((frame+.001)*duration/4);if(!svg.dataset.vector)$$('.athlete-static image',svg).forEach(i=>i.setAttribute('x',String(-width*frame)));$$('.pose-steps button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));const play=$('[data-action="pause-demo"]');if(play)play.textContent='播放演示';}else if(a==='pause-demo'){const stage=$('#demoStage');let svg=$('svg.move-demo',stage);if(!svg)return;if(svg.dataset.manualPhase!==undefined){stage.innerHTML=renderAthleteVector(svg.dataset.move,svg.dataset.character);svg=$('svg.move-demo',stage);stage.classList.remove('is-paused');$$('.pose-steps button').forEach(x=>x.setAttribute('aria-pressed','false'));b.textContent='暂停演示';}else if(svg.animationsPaused()){svg.unpauseAnimations();stage.classList.remove('is-paused');$$('.pose-steps button').forEach(x=>x.setAttribute('aria-pressed','false'));b.textContent='暂停演示';}else{svg.pauseAnimations();b.textContent='播放演示';}}else if(a==='next'&&session){clearInterval(timer);if(session.index===session.moves.length-1)finish();else{session.index++;showSession();}}else if(a==='previous'&&session&&session.index>0){clearInterval(timer);session.index--;showSession();}else if(a==='rest'){clearInterval(timer);const seconds=session?Number(session.moves[session.index].rest)||60:60;let end=Date.now()+seconds*1000;const tick=()=>{const left=Math.max(0,Math.ceil((end-Date.now())/1000));const label=$('#restTimer');if(label)label.textContent=left?`休息 ${left} 秒 · 随时可以继续`:'休息结束';if(!left)clearInterval(timer);};tick();timer=setInterval(tick,500);}else if(a==='water'){if(!requireProfile())return;editEntry().water++;save();render();toast('记下一杯水。按口渴感与身体需求补水。');}else if(a==='method')method();else if(a==='custom-meal')customMeal();else if(a==='photo-meal')openPhotoMeal();else if(a==='adjust')openAdjust();else if(a==='irregular')openModal('饮食调整','偶尔吃多、漏餐或改变计划，不会抹去之前的努力。','<div class="success-icon">◒</div><p class="success-text">正常吃下一餐，补充水分，继续均衡饮食。<br>不需要惩罚性运动，也不需要通过挨饿补偿。</p><button class="primary-button" style="width:100%" data-action="close">关闭</button>');else if(a==='about')openModal('暴击薄肌','把坚持练成日常。','<div class="method-copy"><p>我们把“薄肌”理解为更有力量、更自在的身体状态。没有统一的理想身材，也不设置极端体脂目标。</p><p>你可以选择徒手主题训练与有氧项目，设定适合自己的练休节奏，记录饮食、组数、运动时间与里程。</p><p>这是第一版可操作原型，未来可扩展账号同步与手机 App。当前功能仅在这台设备的浏览器中保存。</p></div><button class="primary-button mt" data-action="profile">建立我的身体档案 →</button>');else if(a==='reset')openModal('删除这台设备上的全部记录？','这会清除身体档案、饮食、训练和体重记录，删除后无法恢复。','<div class="form-footer"><button class="outline-button" data-action="close">保留记录</button><button class="primary-button" data-action="confirm-reset">删除全部记录</button></div>');else if(a==='confirm-reset'){if(typeof CardioRecorder!=='undefined')CardioRecorder.clearDraft?.();state={profile:null,logs:{},weights:[],adjustments:[],changes:[]};save();selectedDate=today;closeModal();render();toast('此设备上的记录已删除。');}});
  document.addEventListener('input',event=>{if(event.target.id==='foodSearch'){foodQuery=event.target.value;const caret=event.target.selectionStart;render();const el=$('#foodSearch');el.focus();el.setSelectionRange(caret,caret);}if(event.target.id==='singleFoodGrams'){const f=foods().find(x=>x.id===event.target.closest('form').dataset.foodId);$('#singleFoodTotal').textContent=Math.round((+event.target.value||0)*f.kcal100/100);}if(event.target.id==='moveSearch'){moveQuery=event.target.value;const el=event.target;const caret=el.selectionStart;render();const replacement=$('#moveSearch');replacement.focus();replacement.setSelectionRange(caret,caret);}if(event.target.closest('#mealForm')){let total=0;$$('#mealForm input').forEach(i=>total+=(+i.value||0)*+i.dataset.density/100);$('#mealTotal').textContent=Math.round(total);}});
  document.addEventListener('change',event=>{if(event.target.closest('#adjustForm'))updateAdjustmentPreview();});
  document.addEventListener('submit',event=>{const f=event.target;event.preventDefault();if(f.id==='profileForm'){const data=new FormData(f);const p={sex:data.get('sex'),height:+data.get('height'),weight:+data.get('weight'),age:+data.get('age'),bodyFat:data.get('bodyFat')===''?null:+data.get('bodyFat'),place:'home',level:data.get('level'),lowImpact:data.get('lowImpact')!=='no',cardioPreference:data.get('cardioPreference'),goal:data.get('goal'),activity:+data.get('activity'),trainDays:+data.get('trainDays'),restDays:+data.get('restDays'),startDate:state.profile?.startDate||today,targetDate:data.get('targetDate'),posture:data.getAll('posture'),screened:data.has('screened')};const e=FitEngine.estimate(p);if(!e.eligible){$('#profileError').textContent=e.reason||'当前信息超出首版自动计划范围，请先寻求专业指导。';return;}if(diff(p.targetDate,today)<7||diff(p.targetDate,today)>365){$('#profileError').textContent='请选择未来7至365天内的复盘日期。';return;}state.profile=p;const currentLog=state.logs[today],currentPlan=plan(today);if(currentLog?.exerciseCompletions&&currentPlan.type==='strength'){currentLog.workout=currentPlan.moves.length>0&&currentPlan.moves.every(m=>currentLog.exerciseCompletions[m.id]===true);if(currentLog.workout)currentLog.title=currentPlan.title;}save();closeModal();selectedDate=today;render();toast('计划已生成');}else if(f.id==='mealForm'){if(!requireProfile())return;const m=mealData.find(x=>x.id===f.dataset.mealId);let total=0;const items=$$('input',f).map((i,n)=>{total+=+i.value*+i.dataset.density/100;return [m.items[n][0],+i.value,+i.dataset.density];});editEntry().meals.push({name:m.title,calories:Math.round(total),items});save();closeModal();render();toast('饮食已记录');}else if(f.id==='singleFoodForm'){if(!requireProfile())return;const food=foods().find(x=>x.id===f.dataset.foodId),grams=+new FormData(f).get('grams');editEntry().meals.push({name:food.name,calories:Math.round(grams*food.kcal100/100),items:[[food.name,grams,food.kcal100]],source:'food-directory'});save();closeModal();render();toast('食物已记录');}else if(f.id==='customMealForm'){const data=new FormData(f);editEntry().meals.push({name:data.get('name'),calories:+data.get('calories')});save();closeModal();render();toast('饮食记录已保存。');}else if(f.id==='weightForm'){if(!requireProfile())return;const data=new FormData(f),date=data.get('date'),value=+data.get('weight');if(date>today||!Number.isFinite(value)||value<30||value>250)return;const existing=state.weights.find(w=>w.date===date);if(existing)existing.value=value;else state.weights.push({date,value});save();render();toast('体重已记录。关注长期趋势。');}else if(f.id==='adjustForm'){updateAdjustmentPreview();if(!pendingAdjustment)return;const result=pendingAdjustment;state.adjustments=result.adjustments;state.profile.targetDate=addDays(profile().targetDate,result.extensionDays);const text=`${fmt(result.missedDate)} 未完成：${result.allocatedMinutes?`未来分摊 ${result.allocatedMinutes} 分钟轻活动，`:''}复盘${result.extensionDays?`顺延 ${result.extensionDays} 天`:'日期不变'}`;state.changes.push({date:today,missedDate:result.missedDate,text});save();closeModal();render();toast('后续安排已更新。继续按自己的节奏来。');}});
  $('#modal').addEventListener('cancel',()=>{clearInterval(timer);session=null;});
